INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_8a90ad72e4', 'LANG-TR-01', 'language', 'languages', 'active', 'كورس اللغة التركية A1 كامل', 'Complete Turkish Language Course (Level A1)', 'احجز مكانك الآن وابدأ رحلتك نحو الاحتراف والوظيفة!', 'Book your spot now and start your journey towards professionalism!', 'انضم لكورس اللغة التركية مع أكاديمية LCT. الكورس مصمم لجميع المستويات ومؤهّل للعمل والوظائف المرتبطة باللغة التركية.', 'Join the Turkish Language Course with LCT Academy. Designed for all levels to qualify you for Turkish language-related jobs.', 'مبتدئ   A1', 'Beginner', '3 شهور للمستوى الواحد (8 محاضرات شهرياً)', '3 MONTHS', 2000.0, '-', '-', '-', '-', 13, 0, 'لا يوجد', 'None');
INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_e842eb4e5d', 'LANG-ZH-01', 'language', 'languages', 'active', 'كورس اللغة الصينية   HSK1,HSK2', 'Chinese Language Course', 'ابدأ رحلتك نحو الاحتراف وتأهل للوظائف المرتبطة باللغة الصينية.', 'Start your journey to professionalism and qualify for Chinese language jobs.', 'كورس شامل مصمم لجميع المستويات،                                                     يهدف إلى تطوير مهارات التواصل واستخدام اللغة الصينية بشكل عملي، وتأهيل المتدربين لسوق العمل والوظائف المرتبطة بها، سواء للمبتدئين أو لمن لديهم أساسيات سابقة.', 'A comprehensive course designed for all levels,                                   aimed at developing practical communication skills in Chinese and preparing trainees for the job market, whether complete beginners or those with basic knowledge.', 'مبتدئ', 'beginner', '3 شهور HSK1+HSK2 (8 محاضرات شهرياً)', '16 Training Hours (8 Lectures, 2 hours each)', 2000.0, '-', '-', '-', '-', 15, 0, 'لا يوجد', 'none');
INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_3b4f0dc4da', 'LANG-EN-02', 'language', 'languages', 'active', 'كورس اللغة الإنجليزية A2,A1', 'English Language Course A2,A1', 'طوّر مستواك في اللغة الإنجليزية وانتقل إلى المستوى الثاني بثقة!', 'Upgrade your English skills and move to the A2 level with confidence', 'كورس اللغة الإنجليزية للمستوى الثاني A2 كاملاً، يهدف لتطوير مهارات المحادثة والقواعد الأساسية وتعزيز التواصل باللغة الإنجليزية على مدار شهرين.', 'Full A2 level English language course aimed at developing basic grammar, conversation skills, and everyday communication over 2 months.', '(A2,A1)', 'Level  A1,A2', '3 شهور A1 + A2 (8 محاضرات شهرياً)', '3 Months per level (8 Lectures per month)', 2000.0, '-', '-', '-', '-', 13, 0, '', '');
INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_b367531369', 'LANG-DE-01', 'language', 'languages', 'active', 'كورس اللغة الألمانية A1 كامل', 'Complete German Language Course (Level A1)', 'ابدأ رحلتك نحو الاحتراف وتأهل للوظائف المرتبطة باللغة الألمانية.', 'Start your journey to professionalism and qualify for German language jobs.', 'كورس شامل لتأسيس اللغة الألمانية يهدف إلى تأهيل المتدربين لسوق العمل والوظائف المرتبطة بها. (ملاحظة: الأسعار لا تشمل الكتب والشهادة).', 'A comprehensive foundational German language course aimed at preparing trainees for the job market and related careers. (Note: Prices do not include books and certificates).', 'المستوى الأول (A1)', 'Level A1', '3 شهور للمستوى الواحد (8 محاضرات شهرياً)', '3 Months per level (8 Lectures per month)', 2000.0, '-', '-', '-', '-', 15, 0, 'لا يوجد', 'none');
INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_b23be166e9', 'LANG-EN-CONV', 'language', 'languages', 'active', 'كورس المحادثة والطلاقة في الإنجليزية', 'English Conversation & Fluency Course', 'تكلّم الإنجليزية بثقة وطلاقة واستفد من العرض والخصم الخاص!', 'Speak English with confidence and fluency—take advantage of our special discount', 'كورس متخصص يركز بالكامل على الممارسة العملية والتحدث الحر لتجاوز الخوف وترديد المصطلحات والتعابير اليومية بطريقة طبيعية ومباشرة خلال شهر واحد. (ملاحظة: السعر لا يشمل الكتب والشهادات)', 'A specialized intensive course focused on practical speaking, real-life conversation, and building fluency within one month. (Note: Price does not include books and certificates)', '3 مستويات', '-', 'شهرين', '-', 2000.0, '-', '-', '-', '-', 15, 0, 'معرفة بالأساسيات وقواعد اللغة الأساسية', 'Basic knowledge of English grammar and vocabulary');
INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_42f28d53c7', 'TECH-ICDL-01', 'computer', 'book-open', 'active', 'كورس رخصة قيادة الحاسب الآلي (ICDL)', 'International Computer Driving Licence (ICDL) Course', 'خطوتك الأولى لنقاط النجاح الوظيفي والاحتراف التكنولوجي!', 'Your first step toward career success and digital efficiency', 'عالم اليوم يتكلم بلغة التكنولوجيا! كورس ICDL الشامل يعلمك كيفية إنجاز المهام في دقائق بدلاً من ساعات من خلال إتقان الأساسيات والإنترنت والبرامج المكتبية (Word, Excel, PowerPoint).', 'Master key computer skills, internet essentials, and Microsoft Office tools to save hours of work and boost your professional efficiency.', 'مبتدئ', 'Beginner', 'محاضرتان أسبوعيًا (كل محاضرة ساعتان)', '2 Sessions per week (2 Hours per session)', 850.0, '-', '-', '-', '-', 15, 0, 'لا يوجد', 'None');
INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_7f42e71404', 'LANG-FR-01', 'language', 'languages', 'active', 'كورس اللغة الفرنسية A1+A2', 'French Language Course', 'ابدأ رحلتك نحو الاحتراف وتأهل للوظائف المرتبطة باللغة الفرنسية.', 'Start your journey to professionalism and qualify for French language jobs.', 'كورس شامل مصمم لجميع المستويات                                       (من مبتدئين إلى محترفين)، يهدف إلى تطوير المهارات اللغوية وتأهيل المتدربين لسوق العمل والوظائف المرتبطة باللغة الفرنسية.', 'A comprehensive course designed for all levels                   (from beginners to professionals), aimed at developing language skills and preparing trainees for the job market and French-related careers.', 'مبتدئ', 'beginner', '3 شهور  (8 محاضرات شهرياً)', '3 Months per level (8 Lectures per month)', 2000.0, '-', '-', '-', '-', 15, 0, 'لا يوجد', 'none');
INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_20837fb3a5', 'TECH-PY-01', 'computer', 'book-open', 'active', 'كورس البرمجة بلغة بايثون (Python)', 'Python Programming Fundamentals Course', 'ابدأ رحلتك في عالم البرمجة وأتقن لغة العصر الأكثر طلباً في سوق العمل!', 'Start your programming journey and master the most in-demand language', 'لغة بايثون هي البوابة الأولى والأسرع لدخول مجالات الذكاء الاصطناعي، وتحليل البيانات، وتطوير المواقع. يُغطي هذا الكورس المفاهيم البرمجية الأساسية من الصفح وحتى كتابة برامج ومشاريع حقيقية باستخدام التفكير البرمجي الصحيح وهياكل البيانات.', 'Python is the easiest and most powerful gateway into Artificial Intelligence, Data Analysis, and Web Development. This course covers core programming concepts from scratch, helping you write clean code and build real-world applications.', 'مبتدئ', 'Beginner', '16 ساعة تدريبية - 8 محاضرات، ساعتان لكل محاضرة', '16 Training Hours - 8 Sessions, 2 Hours per session', 3500.0, '-', '-', '-', '-', 12, 0, 'المعرفة الأساسية لاستخدام الحاسب الآلي والإنترنت (لا يشترط معرفة برمجية)', 'NoneBasic computer literacy (No prior programming background required)');
INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_d7a1c5b1d7', 'PROG-CPP-01', 'language', 'book-open', 'active', 'كورس برمجة C++', 'C++ Programming Course', 'ابدأ رحلتك في عالم البرمجة وتعلم لغة C++ القوية لبناء التطبيقات والألعاب.', 'Start your journey in programming and learn the powerful C++ language to build apps and games.', 'كورس شامل يهدف إلى بناء أساس قوي في البرمجة باستخدام لغة C++، بدءاً من المفاهيم الأساسية وحتى البرمجة كائنية التوجه (OOP)، لتأهيل المتدربين لدخول سوق العمل البرمجي وتطوير الحلول البرمجية.', 'A comprehensive course aimed at building a strong foundation in programming using C++, from basic concepts to Object-Oriented Programming (OOP), preparing trainees to enter the software job market and develop software solutions.', 'مبتدئ', 'beginner', 'شهر واحد لكل مستوى (8 محاضرات للمستوى)', '1 Month per level (8 Lectures per level)', 3500.0, '-', '-', '-', '-', 15, 0, 'لا يوجد (الكورس يبدأ من الصفر ويناسب المبتدئين).', 'none');
INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_1abf0dd095', 'LANG-DE-01', 'language', 'languages', 'active', 'كورس اللغة الألمانية (برايفت)', 'German Language Course (private)', 'ابدأ رحلتك نحو الاحتراف وتأهل للوظائف المرتبطة باللغة الألمانية.', 'Start your journey to professionalism and qualify for German language jobs.', 'كورس شامل لتأسيس اللغة الألمانية يهدف إلى تأهيل المتدربين لسوق العمل والوظائف المرتبطة بها. (ملاحظة: الأسعار لا تشمل الكتب والشهادة).', 'A comprehensive foundational German language course aimed at preparing trainees for the job market and related careers. (Note: Prices do not include books and certificates).', 'المستوى الأول (A1)', 'Level A1', '(8 محاضرات شهرياً مدة المحاضرة ساعة)', '3 Months per level (8 Lectures per month)', 1800.0, '', '', '', '', 1, 1, '', '');
INSERT INTO `courses` (`id`, `code`, `category`, `icon`, `status`, `name_ar`, `name_en`, `tagline_ar`, `tagline_en`, `description_ar`, `description_en`, `level_ar`, `level_en`, `duration_ar`, `duration_en`, `price`, `instructor_ar`, `instructor_en`, `schedule_ar`, `schedule_en`, `seats_total`, `seats_booked`, `prerequisites_ar`, `prerequisites_en`) VALUES ('course_af9df51505', 'LANG - FT 1', 'language', 'book-open', 'active', 'ورشة تدريب ميداني', 'Field Training', 'ورشة تدريب ميداني لكلية ألسن', '*🎓✨ أكاديمية LCT للغات والتدريب والترجمة ✨🎓*  📍 العنوان – الإسماعيلية 🏢 الفرع الرئيسي: شارع شبين عند الموقف الجديد برج بانوراما الدور الثاني  الفرع الثاني: شارع الثلاثيني، أعلى محمصة الدراويش 📌 ناصية شارع فاروق  *💙 مستنيينكم في LCT Academy 💙*  📚✨ خطوتك الأولى لمستقبل أفضل ✨📚', 'فرصة ذهبية لطلبة كليات الألسن! تم فتح باب التدريب الصيفي الميداني المدعوم لطلاب الألسن. احصل على محاضرتين (4 ساعات) فقط بتكلفة 250 جنيه. المنحة تشمل الشهادة، الاستمارة، وجميع المحاضرات. عدد المقاعد محدود، احجز الآن قبل نفاد العدد. لا تفوت الفرصة!"INSERT INTO `customers` (`phone`, `full_name`, `email`, `national_id`, `created_at`) VALUES ('01002281446', 'Hager Ali Mohamed Ali', 'ha1678290@gmail.com', '30506140300182', '2026-10-14 10:01:29');
